grant create on schema api,app_private to git_tutor_commands;
create function app_private.payment_payer_intent_dto(p_link_id uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('plan_link_id',l.id,'version',l.version,'transfer_id',l.transfer_id,'payment_plan_id',l.payment_plan_id,'plan_hash',l.source_intent_hash,'expires_at',l.expires_at,'transfer_amount_minor',t.amount_minor,'currency',t.currency,'targets',app_private.payment_plan_read_dto(l.payment_plan_id)->'targets','state',case when l.state='awaiting_payer_acceptance' and(l.expires_at<=now() or p.state<>'active' or l.payer_binding_id is distinct from t.current_payer_binding_id or p.evidence_version<>r.current_evidence_version) then 'invalidated' else l.state end,'accepted_at',(select accepted_at from app_private.transfer_payment_plan_acceptances where plan_link_id=l.id)) from app_private.transfer_payment_plan_links l join finance_private.incoming_transfers t on t.id=l.transfer_id join app_private.payment_allocation_plans p on p.id=l.payment_plan_id join app_private.receipts r on r.id=p.receipt_id where l.id=p_link_id
$$;
create function api.get_transfer_payment_plan(p_plan_link_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();begin if not exists(select 1 from app_private.transfer_payment_plan_links l join finance_private.incoming_transfers t on t.id=l.transfer_id join finance_private.transfer_payer_bindings b on b.id=t.current_payer_binding_id where l.id=p_plan_link_id and b.payer_account_id=actor) then raise exception 'NOT_FOUND';end if;return app_private.payment_payer_intent_dto(p_plan_link_id);end $$;
create function app_private.payment_consent_page(p_kind text,p_target uuid,p_source uuid,p_cursor text,p_limit integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;purchase app_private.package_purchases%rowtype;source finance_private.customer_credit_lots%rowtype;begin
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 if p_kind='plans' then
  perform app_private.payment_assert_receipt_read(actor,p_target);
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_plan_read_dto(x.id)) order by x.created_at desc,x.id desc),'[]') into rows from(select p.* from app_private.payment_allocation_plans p where p.receipt_id=p_target and p.state='active' and p.evidence_version=(select current_evidence_version from app_private.receipts where id=p_target) and(p_cursor is null or(p.created_at,p.id)<(after_at,after_id)) order by p.created_at desc,p.id desc limit p_limit+1)x;
 elsif p_kind='payer_intents' then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',app_private.payment_payer_intent_dto(x.id)) order by x.created_at desc,x.id desc),'[]') into rows from(select l.* from app_private.transfer_payment_plan_links l join finance_private.incoming_transfers t on t.id=l.transfer_id join finance_private.transfer_payer_bindings b on b.id=t.current_payer_binding_id where b.payer_account_id=actor and(p_cursor is null or(l.created_at,l.id)<(after_at,after_id)) order by l.created_at desc,l.id desc limit p_limit+1)x;
 elsif p_kind in('credit_sources','credit_policies') then
  select * into purchase from app_private.package_purchases where id=p_target;if purchase.id is null then raise exception 'NOT_FOUND';end if;perform app_private.package_assert_scope(actor,purchase.learner_id,'payments');
  if p_kind='credit_sources' then
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('source_credit_id',x.id,'version',x.financial_version,'title','Available settled credit','currency',x.currency,'available_minor',x.available)) order by x.created_at desc,x.id desc),'[]') into rows from(select l.*,a.version financial_version,least(finance_private.finance_credit_available(l.id),(finance_private.finance_transfer_balance(l.transfer_id)->>'available_minor')::bigint) available from finance_private.customer_credit_lots l join finance_private.credit_lot_accounts a on a.credit_lot_id=l.id join finance_private.incoming_transfers t on t.id=l.transfer_id where l.payer_account_id=actor and t.current_payer_binding_id=l.payer_binding_id and t.state='settled' and finance_private.finance_transfer_balance(t.id)->>'reconciliation_state'='clear' and finance_private.finance_credit_available(l.id)>0 and(finance_private.finance_transfer_balance(t.id)->>'available_minor')::bigint>0 and(p_cursor is null or(l.created_at,l.id)<(after_at,after_id)) order by l.created_at desc,l.id desc limit p_limit+1)x;
  else
   select * into source from finance_private.customer_credit_lots where id=p_source;if source.id is null or source.payer_account_id<>actor then raise exception 'NOT_FOUND';end if;
   if finance_private.finance_credit_available(source.id)<=0 or(finance_private.finance_transfer_balance(source.transfer_id)->>'available_minor')::bigint<=0 or finance_private.finance_transfer_balance(source.transfer_id)->>'reconciliation_state'<>'clear' then return jsonb_build_object('items','[]'::jsonb,'next_cursor',null);end if;
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('grant_policy_version_id',x.id,'name',x.content->>'name','currency',x.content->>'currency','valuation_rule','reviewed_exact_source_credit','maximum_credit_quanta_per_grant',x.content->'maximum_credit_quanta_per_grant','maximum_carrying_value_minor_per_grant',x.content->'maximum_carrying_value_minor_per_grant')) order by x.created_at desc,x.id desc),'[]') into rows from(select p.* from app_private.package_grant_policy_versions p where p.status='approved' and p.effective_at<=now() and p.content->>'valuation_rule'='reviewed_exact_source_credit' and p.content->>'currency'=source.currency and p.content->'eligible_package_contract_version_ids' @> jsonb_build_array(purchase.contract_version_id) and(p_cursor is null or(p.created_at,p.id)<(after_at,after_id)) order by p.created_at desc,p.id desc limit p_limit+1)x;
  end if;
 else raise exception 'VALIDATION_ERROR';end if;
 return app_private.package_page(rows,p_limit);
end $$;
create function api.list_payment_plans(p_receipt_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_consent_page('plans',p_receipt_id,null,p_cursor,p_limit)$$;
create function api.list_my_payment_plan_requests(p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_consent_page('payer_intents',null,null,p_cursor,p_limit)$$;
create function api.list_credit_conversion_sources(p_package_purchase_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_consent_page('credit_sources',p_package_purchase_id,null,p_cursor,p_limit)$$;
create function api.list_credit_conversion_policies(p_package_purchase_id uuid,p_source_credit_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_consent_page('credit_policies',p_package_purchase_id,p_source_credit_id,p_cursor,p_limit)$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname in('payment_payer_intent_dto','payment_consent_page')) or(n.nspname='api' and p.proname in('get_transfer_payment_plan','list_payment_plans','list_my_payment_plan_requests','list_credit_conversion_sources','list_credit_conversion_policies')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private from git_tutor_commands;
notify pgrst,'reload schema';
